mapper.select:
select m.id from sys_menu m left join sys_role_menu rm on m.id = rm.menu_id where rm.role_id = #{roleId}
and m.id not in (select m.parent_id from sys_menu m inner join sys_role_menu rm on m.id = rm.menu_id and rm.role_id = #{roleId})
order by m.parent_id, m.sort

select distinct m.id, m.parent_id, m.path, m.route_name, m.`name`, m.component, m.param, m.iframe, m.cache, m.state, m.visible, m.redirect, m.icon, m.menu_type, ifnull(m.power,'') as power, m.sort, m.description, m.create_by, m.create_time, m.update_by, m.update_time, m.deleted from sys_menu m where m.deleted = 0
AND m.name like concat('%', #{name}, '%')
AND m.visible = #{visible}
AND m.state = #{state}
order by m.parent_id, m.sort

select distinct m.id, m.parent_id, m.path, m.route_name, m.`name`, m.component, m.param, m.iframe, m.cache, m.state, m.visible, m.redirect, m.icon, m.menu_type, ifnull(m.power,'') as power, m.sort, m.description, m.create_by, m.create_time, m.update_by, m.update_time, m.deleted from sys_menu m left join sys_role_menu rm on m.id = rm.menu_id left join sys_user_role ur on rm.role_id = ur.role_id left join sys_role ro on ur.role_id = ro.id where ur.user_id = #{userId} AND m.deleted = 0
AND m.name like concat('%', #{name}, '%')
AND m.visible = #{visible}
AND m.state = #{state}
order by m.parent_id, m.sort
